WITH with_dims AS (SELECT a.*, d.shipping_fee, d.discount FROM shipments a INNER JOIN orders d ON a.order_id = d.id) SELECT DATE_TRUNC('MONTH', delivered_date) AS activity_month, status, SORT_ARRAY(COLLECT_SET(carrier)) AS carrier_list, COUNT(CASE WHEN status = 'RETURNED' THEN 1 END) AS returned_count, COUNT(*) FILTER (WHERE status = 'LOST') AS lost_rows, ROUND(AVG(shipping_fee), 2) AS avg_shipping_fee, SUM(shipping_fee) AS total_shipping_fee FROM with_dims GROUP BY GROUPING SETS ((DATE_TRUNC('MONTH', delivered_date), status), (DATE_TRUNC('MONTH', delivered_date)), ()) ORDER BY returned_count DESC NULLS FIRST
